{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "სავარძლის ქვეშ მდებარე ყვითელი მარეგულირებელი ღილაკი ფოტოზე არ ჩანს და ნაწილების სიაში არ არის. რეგულირების შემდეგ დარწმუნდი, რომ სავარძელი დაფიქსირებულია."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "წონის შესარჩევი ყვითელი ქინძისთავი და ფილების შესარჩევი ხვრელები ფოტოზე არ ჩანს და ნაწილების სიაში არ არის. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები უძრავად დევს."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {
          "part": "p1",
          "label": "მოჭიდება მოხრილ ბოლოებთან",
          "tone": "brand"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p1", "p2", "p3"],
      "avoid": [],
      "markers": [
        {
          "part": "p2",
          "label": "მარცხენა მუხლი ბალიშის ქვეშ",
          "tone": "brand"
        },
        {
          "part": "p3",
          "label": "მარჯვენა მუხლი ბალიშის ქვეშ",
          "tone": "brand"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "სავარძელი ფოტოზე დაფარულია და მისთვის ID არ არის მოცემული; მონიშნულია მხოლოდ ხილული სახელური და ორივე ბალიში."
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {
          "part": "p1",
          "label": "ჩამოწიე კონტროლირებულად",
          "tone": "brand"
        }
      ],
      "arrows": [
        {
          "part": "p1",
          "type": "move",
          "dir": "down"
        },
        {
          "part": "p1",
          "type": "move",
          "dir": "up"
        }
      ],
      "tools": [],
      "warn": "არ მოქაჩო ბიძგით და არ ჩამოიტანო სახელური კისრის უკან. 2 წამი ინსტრუქციაში მითითებული ტემპია და არა ფოტოდან დადგენილი მონაცემი."
    }
  ],
  "unknown_parts": [
    "სავარძლის ქვეშ მდებარე ყვითელი სიმაღლის მარეგულირებელი ღილაკი",
    "სავარძელი",
    "წონის შესარჩევი ყვითელი ქინძისთავი და ფილების შესარჩევი ხვრელები"
  ]
}
